INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A fabric''s GSM before wet processing is 160, and its length shrinks by 4% and width shrinks by 3% during processing (with the same total fiber mass retained). Approximately what is the new GSM after processing?', '["≈ 171.9 GSM","≈ 160 GSM","≈ 148.5 GSM","≈ 153.9 GSM"]'::jsonb, '≈ 171.9 GSM', 'Since the same mass now occupies a smaller area, new GSM = old GSM ÷ ((1−length shrink%) × (1−width shrink%)) = 160 ÷ (0.96 × 0.97) = 160 ÷ 0.9312 ≈ 171.8 GSM.', 2, '{"gsm-shrinkage-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A fabric''s GSM before wet processing is 140, and its length shrinks by 5% and width shrinks by 4% during processing (same total fiber mass retained). Approximately what is the new GSM after processing?', '["≈ 153.5 GSM","≈ 140 GSM","≈ 127.7 GSM","≈ 146.3 GSM"]'::jsonb, '≈ 153.5 GSM', 'New GSM = old GSM ÷ ((1−length shrink%) × (1−width shrink%)) = 140 ÷ (0.95 × 0.96) = 140 ÷ 0.912 ≈ 153.5 GSM.', 2, '{"gsm-shrinkage-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A chemical dosing tank needs 45 g/L concentration for a total liquor volume of 5,000 liters. How many kg of the chemical must be added?', '["225 kg","45 kg","5 kg","22.5 kg"]'::jsonb, '225 kg', 'Total chemical = concentration (g/L) × volume (L) = 45 × 5,000 = 225,000 g = 225 kg.', 1, '{"chemical-dosing-tank-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A chemical dosing tank needs 35 g/L concentration for a total liquor volume of 8,000 liters. How many kg of the chemical must be added?', '["280 kg","35 kg","8 kg","28 kg"]'::jsonb, '280 kg', 'Total chemical = concentration (g/L) × volume (L) = 35 × 8,000 = 280,000 g = 280 kg.', 1, '{"chemical-dosing-tank-calc"}'::text[]);
